<script setup>
import { computed,onMounted,reactive,ref } from 'vue';import { api } from '../api'
const chapters=ref([]),points=ref([]),message=ref(''),error=ref('');const chapterForm=reactive({code:'CH10',name:'',description:'',sortOrder:10,enabled:true});const pointForm=reactive({chapterId:'',code:'',name:'',description:'',sortOrder:1,enabled:true})
const grouped=computed(()=>chapters.value.map(c=>({...c,points:points.value.filter(p=>p.chapterId===c.id)})))
async function load(){try{[chapters.value,points.value]=await Promise.all([api('/api/admin/chapters'),api('/api/admin/knowledge-points')]);if(!pointForm.chapterId&&chapters.value[0])pointForm.chapterId=chapters.value[0].id}catch(e){error.value=e.message}}
async function addChapter(){await run(async()=>{await api('/api/admin/chapters',{method:'POST',body:chapterForm});chapterForm.name='';await load()},'章节已保存')}
async function addPoint(){await run(async()=>{await api('/api/admin/knowledge-points',{method:'POST',body:pointForm});pointForm.name='';pointForm.code='';await load()},'知识点已保存')}
async function editChapter(c){const name=prompt('章节名称',c.name);if(name===null)return;const description=prompt('章节说明',c.description);if(description===null)return;const sortOrder=Number(prompt('排序',String(c.sortOrder)));await run(()=>api(`/api/admin/chapters/${c.id}`,{method:'PUT',body:{...c,name,description,sortOrder,expectedVersion:c.version}}).then(load),'章节已更新')}
async function toggleChapter(c){await run(()=>api(`/api/admin/chapters/${c.id}`,{method:'PUT',body:{...c,expectedVersion:c.version,enabled:!c.enabled}}).then(load),c.enabled?'章节已停用':'章节已启用')}
async function editPoint(p){const name=prompt('知识点名称',p.name);if(name===null)return;const description=prompt('知识点说明',p.description);if(description===null)return;const sortOrder=Number(prompt('排序',String(p.sortOrder)));await run(()=>api(`/api/admin/knowledge-points/${p.id}`,{method:'PUT',body:{...p,name,description,sortOrder,expectedVersion:p.version}}).then(load),'知识点已更新')}
async function togglePoint(p){await run(()=>api(`/api/admin/knowledge-points/${p.id}`,{method:'PUT',body:{...p,expectedVersion:p.version,enabled:!p.enabled}}).then(load),p.enabled?'知识点已停用':'知识点已启用')}
async function run(fn,text){error.value='';message.value='';try{await fn();message.value=text}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template><section><div class="page-head"><div><h2>章节与知识点</h2><p class="muted">维护固定课程目录；停用代替删除，历史引用继续保留。</p></div></div><div class="grid two"><form class="card grid" @submit.prevent="addChapter"><h3>新增章节</h3><label class="field">章节编码<input v-model="chapterForm.code" required pattern="CH[0-9]{2}"></label><label class="field">名称<input v-model="chapterForm.name" required></label><label class="field">说明<textarea v-model="chapterForm.description"></textarea></label><label class="field">排序<input v-model.number="chapterForm.sortOrder" type="number" min="0"></label><button class="primary">保存章节</button></form><form class="card grid" @submit.prevent="addPoint"><h3>新增知识点</h3><label class="field">所属章节<select v-model="pointForm.chapterId"><option v-for="c in chapters" :key="c.id" :value="c.id">{{c.code}} · {{c.name}}</option></select></label><label class="field">知识点编码<input v-model="pointForm.code" required placeholder="CH03-KP02" pattern="CH[0-9]{2}-KP[0-9]{2}"></label><label class="field">名称<input v-model="pointForm.name" required></label><label class="field">说明<textarea v-model="pointForm.description"></textarea></label><label class="field">排序<input v-model.number="pointForm.sortOrder" type="number" min="0"></label><button class="primary">保存知识点</button></form></div><p class="success">{{message}}</p><p class="error">{{error}}</p><div class="card directory"><article v-for="chapter in grouped" :key="chapter.id"><header><span class="code">{{chapter.code}}</span><h3>{{chapter.name}}</h3><small>v{{chapter.version}}</small><span class="badge" :class="{active:chapter.enabled}">{{chapter.enabled?'启用':'停用'}}</span><span class="chapter-actions"><button class="secondary" @click="editChapter(chapter)">编辑</button><button class="secondary" @click="toggleChapter(chapter)">{{chapter.enabled?'停用':'启用'}}</button></span></header><div v-for="p in chapter.points" :key="p.id" class="point"><div><span class="code">{{p.code}}</span><strong>{{p.name}}</strong><small>v{{p.version}}</small></div><span class="actions"><button class="secondary" @click="editPoint(p)">编辑</button><button class="secondary" @click="togglePoint(p)">{{p.enabled?'停用':'启用'}}</button></span></div></article></div></section></template>
<style scoped>.directory{margin-top:18px;padding-left:30px}.directory article{border-left:2px solid #cdd8d7;padding:2px 0 20px 24px}.directory article>header{display:flex;align-items:center;gap:12px}.directory h3{margin:0}.chapter-actions{display:flex;gap:6px;margin-left:auto}.point{display:flex;justify-content:space-between;align-items:center;margin-top:12px;padding:11px 13px;background:#f7f8fa;border-radius:8px}.point div{display:flex;gap:12px;align-items:center}.point small{color:#7a8495}</style>
